using System;
using System.Collections.Generic;
using Robust.Client.AutoGenerated;
using Robust.Client.UserInterface.Controls;
using Robust.Client.UserInterface.CustomControls;
using Robust.Client.UserInterface.XAML;

namespace Content.Client.DeadSpace.Administration.Announce
{
    [GenerateTypedNameReferences]
    public sealed partial class AnnouncementTemplatesWindow : DefaultWindow
    {
        public event Action<string>? OnTemplateSelected;

        public AnnouncementTemplatesWindow()
        {
            RobustXamlLoader.Load(this);

            foreach (var (name, text) in GetTemplates())
            {
                var button = new Button
                {
                    Text = name,
                    HorizontalExpand = true,
                    TextAlign = Label.AlignMode.Left,
                    SetHeight = 30
                };
                button.OnPressed += _ =>
                {
                    OnTemplateSelected?.Invoke(text);
                    Close();
                };

                TemplatesContainer.AddChild(button);
            }
        }

        private static List<(string Name, string Text)> GetTemplates()
        {
            // DS14-Soyuz-start
            return new List<(string Name, string Text)>
            {
                ("Запрос отчёта о ситуации", "Действующему Руководству предприятия! В соответствии с постановлением Звёздного Совета, для реализации пункта «о взаимодействии и связи», мы запрашиваем у вас протокол о ситуации на предприятии и ходе плановых задач. С настоящего временного ориентира период на ответ составляет пятнадцать минут. Девиантное поведение в части документооборота, умышленное пренебрежение требованиями и иные факторы могут непосредственно обусловить санкции. И помните: Советы заботятся о вас!"),
                ("Запрос отчёта о ситуации [Осталось 5 минут]", "Действующему Руководству предприятия! Настоящий приказ Генерального Штаба до сих пор не был удовлетворён. Сообщаем, что интервал для отчёта пять минут. Умышленное пренебрежение требованиями приведёт к личным санкциям против Высшего руководящего состава и безличным санкциям против Руководства объекта. И помните: Советы хранят вас!"),
                ("Выполнение цели", "Внимание, рабочему коллективу предприятия! Звездный Совет, в лице Генерального Штаба, получил отчётность о ситуации на предприятии. Плановые задачи обозначены выполненными. Заработные платы сформированы в полном объёме, дополнительных премий выплачено не будет. Протоколы трансфера вступают в силу. Советсткий Союз — стремление к единству!"),
                ("Частичное выполнение цели", "Внимание, рабочему коллективу предприятия! Звездный Совет, в лице Генерального Штаба, получил отчётность о ситуации на предприятии. Плановые задачи обозначены частично выполненными. Заработные платы буду содержать только оклад, дополнительных премий выплачено не будет. Протоколы трансфера вступают в силу. Советсткий Союз — стремление к единству!"),
                ("Провал цели", "Внимание, рабочему коллективу предприятия! Звездный Совет, в лице Генерального Штаба, получил отчётность о ситуации на предприятии. Плановые задачи обозначены проваленными. Заработные платы буду содержать только оклад, дополнительных премий выплачено не будет. Протоколы трансфера вступают в силу. Советсткий Союз — стремление к единству!"),
                ("Провал цели [КВБ]", "Внимание, рабочему коллективу предприятия! Генеральный штаб получил отчет о ликвидации угрозы силами Комиссариата Всесоюзной Безопасности. Штабом было принято решение о завершении рабочей смены. План на данную смену аннулируется. Оклад рабочему коллективу задержан не будет. Всему экипажу беспрекословно следовать приказам бойцов НКВБ для последующей эвакуации. Протоколы трансфера одобрены."),
                ("Дополнительная цель", "Действующему Руководству предприятия! Звёздный совет, в лице Генерального Штаба, получил отчётность о выполнении плановых задач. Оклад за данную смену увеличен на 15 процентов. В связи с крайне эффективным выполнением поставленной задачи, Звёздным советом было принято решение о выдаче дополнительной плановой задачи для гарантированного премирования коллектива. Более подробная информация о новой задаче была отправлена на факс Капитана. И помните: Советы хранят вас!"),
                ("Отправка Представителя", "Действующему Руководству предприятия! Администратор Генерального Штаба утвердил отправку своего Представителя на ваш объект. Всему Руководящему составу приказано собраться в зоне совещаний. Игнорирование настоящего приказа недопустимо. И помните: Советы хранят вас!"),
                ("Звонок ПЦК на голопад", "Действующему Руководству предприятия! Генеральным штабом был получен запрос на отправку нашего Представителя для проведения внутренних разбирательств. Ввиду некоторых обстоятельств Представитель Генерального Штаба не может явиться лично на объект, однако было принято решение об проведении разбирательств через станционный голопад. Всему Руководящему составу приказано собраться на мосту в течении следующих пяти минут. Игнорирование настоящего приказа недопустимо. И помните: Советы хранят вас!"),
                ("Изменение заработной платы", "Действующему Руководству предприятия! Исходя из последней полученной документации, Генеральным Штабом было принято решение об изменении оклада [отделу/сотруднику] на [СКОЛЬКО] процентов.  И помните: Советы хранят вас!"),
                ("Снятие юридической неприкосновенности", "Действующему Руководству предприятия! Исходя из последней полученной документации, Администратором Генерального Штаба было принято решение о снятии юридической неприкосновенности с [Капитана/Системного Агента Прокуратуры/Оперативника КГБ] станции. Советской Гражданской Милиции приказано провести процедуру ареста данного члена экипажа по статье 407 Правил Внутреннего Распорядка. Игнорирование настоящего приказа недопустимо. И помните: Советы хранят вас!")
            };
            // DS14-Soyuz-end
        }
    }
}
